prompt --application/shared_components/logic/application_processes/openminpdf_bol
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(671609494476203528)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'OpenMinPDF_BOL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    bBlob blob;',
'    vMimeType varchar2(50);',
'begin',
'    select  BLOB_FILE, MIME_TYPE',
'    into    bBlob, vMimeType',
'    from    RMAIS_ATTACHMENTS_BOL',
'    where   EFD_HEADER_ID = V(''P7_ID'');',
'',
'    owa_util.mime_header(vMimeType,false);',
'    htp.p(''Content-Length: '' || dbms_lob.getlength(bBlob));',
'    owa_util.http_header_close;',
'    wpg_docload.download_file(bBlob);',
'',
'exception',
'    when no_data_found then',
'        null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>1
);
end;
/
prompt --application/shared_components/logic/application_processes/openminpdf_header
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(673908591865758170)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'OpenMinPDF_HEADER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    bBlob blob;',
'    vMimeType varchar2(50);',
'begin',
'    select  nvl(BLOB_FILE,PDF_FILE),''application/pdf''',
'    into    bBlob, vMimeType',
'    from    RMAIS_EFD_HEADERS',
'    where   EFD_HEADER_ID = V(''P14_ID'');',
'',
'    owa_util.mime_header(vMimeType,false);',
'    htp.p(''Content-Length: '' || dbms_lob.getlength(bBlob));',
'    owa_util.http_header_close;',
'    wpg_docload.download_file(bBlob);',
'    ',
'exception',
'    when no_data_found then',
'        null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>1
);
end;
