,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * from (',
'SELECT  line_number',
',''1'' link',
',item_code',
',nvl(source_document_type,''PO'') Type_lin',
',source_doc_number Pedido',
',source_doc_line_num',
unistr('--,decode(source_doc_line_id,null,''N\00E3o Localizado'',''Localizado'') status_op'),
'/*,CASE WHEN nvl(source_document_type,''PO'') = ''PO'' and source_doc_line_id is not null then ''PO Localizada''',
