wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(1788915956781810315)
,p_event_id=>wwv_flow_imp.id(1788915773083810314)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    update  rmais_efd_headers',
'    set     Withholding = :P8_WITHHOLD',
'    where   efd_header_id = :P8_EFD_HEADER_ID;',
'    --',
'    update  rmais_efd_lines',
'    set     destination_type = decode(:P8_SOURCE,''FDC'',''INVENTORY'',''AP'',''EXPENSE'',:P8_SOURCE),',
'            source_document_type = :P8_TYPE_LIN',
'    where   efd_header_id = :P8_EFD_HEADER_ID;',
'    --',
'    if nvl(:P8_REPLICAR_INFOS,''N'') = ''Y'' then ',
'        update rmais_efd_lines',
'        set     source_document_type = :P8_TYPE_LIN,',
'                INTENDED_USE         = :P8_USO_PRETENTIDO,',
'                USER_DEFINED         = :P8_USER_DEFINED,',
'                PRODUCT_CATEGORY     = :P8_PRODUCTCATEGORY',
'        where   efd_header_id = :P8_EFD_HEADER_ID;',
'    else',
'        update  rmais_efd_lines',
'        set     source_document_type = :P8_TYPE_LIN,',
'                INTENDED_USE         = :P8_USO_PRETENTIDO,',
'                USER_DEFINED         = :P8_USER_DEFINED,',
'                PRODUCT_CATEGORY     = :P8_PRODUCTCATEGORY',
'        where   efd_line_id = :P8_LINE_ID;',
'    end if;',
'    --',
'end;'))
,p_attribute_02=>'P8_COND_PAG,P8_EFD_HEADER_ID,P8_MOEDA,P8_SOURCE,P8_TYPE_LIN,P8_USO_PRETENTIDO,P8_USER_DEFINED,P8_PRODUCTCATEGORY,P8_REPLICAR_INFOS,P8_LINE_ID,P8_WITHHOLD'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
