'                a.task_number, --"TRANSACTION_ID","CNPJ","RECEIVER","TOTAL_PO","PO_HEADER_ID","PO_NUM","PO_TYPE","TOMADOR","TOMADOR_CNPJ","PRC_BU_ID","VENDOR_NAME","VENDOR_ID","VENDOR_SITE_ID","VENDOR_SITE_CODE","FORNECEDOR_CNPJ","CURRENCY_CODE","INF'
||'O_DOC","INFO_TERM","PO_SEQ","INFO_PO","INFO_ITEM","INFO_SHIP","PO_LINE_ID","LINE_TYPE_ID","LINE_NUM","ITEM_ID","CATEGORY_ID","ITEM_DESCRIPTION","UOM_CODE","UNIT_PRICE","QUANTITY_LINE","PRC_BU_ID_LIN","REQ_BU_ID_LIN","TAXABLE_FLAG_LIN","ORDER_TYPE_LOO'
||'KUP_CODE","PURCHASE_BASIS","MATCHING_BASIS","LINE_LOCATION_ID","DESTINATION_TYPE_CODE","TRX_BUSINESS_CATEGORY","PRC_BU_ID_LOC","REQ_BU_ID_LOC","PRODUCT_TYPE","ASSESSABLE_VALUE","QUANTITY_SHIP","QUANTITY_RECEIVED","QUANTITY_ACCEPTED","QUANTITY_REJECTE'
||'D","QUANTITY_BILLED","QUANTITY_CANCELLED","SHIP_TO_LOCATION_ID","NEED_BY_DATE","PROMISED_DATE","LAST_ACCEPT_DATE","PRICE_OVERRIDE","TAXABLE_FLAG","RECEIPT_REQUIRED_FLAG","SHIP_TO_ORGANIZATION_ID","SHIPMENT_NUM","SHIPMENT_TYPE","FUNDS_STATUS","DESTINA'
||'TION_TYPE_DIST","PRC_BU_ID_DIST","REQ_BU_ID_DIST","ENCUMBERED_FLAG","UNENCUMBERED_QUANTITY","AMOUNT_BILLED","AMOUNT_CANCELLED","QUANTITY_FINANCED","AMOUNT_FINANCED","QUANTITY_RECOUPED","AMOUNT_RECOUPED","RETAINAGE_WITHHELD_AMOUNT","RETAINAGE_RELEASED'
||'_AMOUNT","TAX_ATTRIBUTE_UPDATE_CODE","PO_DISTRIBUTION_ID","BUDGET_DATE","CLOSE_BUDGET_DATE","DIST_INTENDED_USE","SET_OF_BOOKS_ID","CODE_COMBINATION_ID","QUANTITY_ORDERED","QUANTITY_DELIVERED","CONSIGNMENT_QUANTITY","REQ_DISTRIBUTION_ID","DELIVER_TO_L'
||'OCATION_ID","DELIVER_TO_PERSON_ID","RATE_DATE","RATE","ACCRUED_FLAG","ENCUMBERED_AMOUNT","UNENCUMBERED_AMOUNT","DESTINATION_ORGANIZATION_ID","PJC_TASK_ID","TASK_NUMBER","TASK_ID","LOCATION_ID","COUNTRY","POSTAL_CODE","LOCAL_DESCRIPTION","EFFECTIVE_ST'
