wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(570699566731285603)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Collection_v2'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    r$po RMAIS_PROCESS_PKG.t$po_line;',
'begin',
'    execute immediate q''[alter session set NLS_NUMERIC_CHARACTERS=''.,'']'';',
'    --  APEX_COLLECTION.DELETE_COLLECTION(p_collection_name => ''RMAIS_PO_OK'');',
'    --  APEX_COLLECTION.CREATE_COLLECTION(p_collection_name => ''RMAIS_PO_OK'');',
'    --  rmais_process_pkg.Set_Po_Array(:P8_CNPJ_FORNECEDOR,:P8_CNPJ_TOMADOR);',
'    begin',
'        --',
'        if APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''RMAIS_PO_OK'') THEN',
'            APEX_COLLECTION.DELETE_COLLECTION(p_collection_name => ''RMAIS_PO_OK'');',
'            APEX_COLLECTION.CREATE_COLLECTION(p_collection_name => ''RMAIS_PO_OK'');',
'        else',
'            APEX_COLLECTION.CREATE_COLLECTION(p_collection_name => ''RMAIS_PO_OK'');',
'        end if;',
'    end;',
'    r$po := RMAIS_PROCESS_PKG.Cursor_PO_Line(p_transaction_id => :G_TRANSACTION_ID);',
'    for x in (',
'        select  a.po_num pedido, ',
'                a.po_line_id, ',
'                a.line_num, ',
'                a.item_description,',
'                a.UOM_CODE, ',
'                a.UOM_DESC,',
'                a.UNIT_PRICE, ',
'                a.QUANTITY_LINE, ',
'                a.LINE_LOCATION_ID,',
'                a.need_by_date,',
'                a.promised_date,',
'                a.po_header_id,',
'                a.info_po,',
'                a.item_number,',
'                a.description,',
'                a.info_term,',
'                a.info_item,',
'                a.task_number,',
'                a.destination_type, ',
'                a.NCM,',
'                a.match_option,',
'                a.RECEIPT_NUM,',
'                a.RECEIPT_LINE_NUM,',
'                a.RECEIPT_QUANTITY_DELIV',
'        from    table(r$po) a',
'    ) loop',
'        null;',
'        apex_collection.add_member(',
'            p_collection_name   => ''RMAIS_PO_OK'',',
'            p_c001              => x.pedido,',
'            p_c002              => x.item_description,',
'            p_c003              => x.UOM_CODE,',
'            p_c010              => nls_num_char(to_char(x.unit_price)),',
'            p_n004              => nls_num_char(x.quantity_line),',
'            p_n005              => x.line_location_id,',
'            p_c004              => x.need_by_date,',
'            p_c005              => x.promised_date,',
'            p_n001              => x.po_line_id,',
'            p_n002              => x.line_num,',
'            p_c009              => to_char(x.po_header_id),',
'            p_c006              => x.info_po,',
'            p_c007              => x.item_number,',
'            p_c008              => x.description,',
'            p_c011              => x.info_term,',
'            p_c012              => x.info_item,',
'            p_c013              => x.task_number,',
'            p_c014              => x.destination_type,',
'            p_c015              => x.ncm,',
'            p_c016              => x.UOM_DESC,',
'            p_c017              => x.match_option,',
'            p_c018              => x.RECEIPT_NUM,',
'            p_c019              => x.RECEIPT_LINE_NUM,',
'            p_c020              => x.RECEIPT_QUANTITY_DELIV',
'        );',
'    end loop;',
'    --',
'    execute immediate q''[alter session set NLS_NUMERIC_CHARACTERS='',.'']'';',
'    --',
'exception when others then',
'    raise_application_error(-20033,''Erro ao buscar PO: ''||sqlerrm);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>536413217899973695
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1633999399283391624)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get infos lines'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':G_TRANSACTION_ID := null;',
'--',
'SELECT  item_descr_efd',
'       ,item_code_efd',
'       ,INTENDED_USE',
'       ,user_defined  ',
'       ,product_category',
'       ,fiscal_classification_to',
'       ,source_doc_line_id',
'       ,source_doc_number',
'       ,source_doc_id',
'       ,line_location_id',
'       ,order_info',
'       ,item_code_efd',
'       ,item_descr_efd',
'       ,item_info',
'       ,uom_to',
'       ,uom_to_desc',
'       ,source_doc_line_num',
'       ,source_document_type',
'       ,fiscal_classification_to',
'       ,cfop_to',
'       ,destination_type',
'       ,replace(to_char(nvl(unit_price_original,unit_price)),'','',''.'')',
'       ,replace(to_char(nvl(quantity_original,line_quantity)),'','',''.'')',
'       ,replace(to_char(round(nls_num_char(nvl(unit_price_original,unit_price)) + ((nvl(ipi_amount,0) + nvl(icms_st_amount,0)+ nvl(FREIGHT_LINE_AMOUNT,0))/nls_num_char(nvl(quantity_original,line_quantity))),2)),'','',''.'')',
'       ,replace(to_char((nls_num_char(nvl(unit_price_original,unit_price)) * nvl(quantity_original,line_quantity)) + nvl(ipi_amount,0) + nvl(icms_st_amount,0)+ nvl(FREIGHT_LINE_AMOUNT,0)),'','',''.'')',
'  into :P8_ITEM_DESC_OK',
'       ,:P8_ITEM_OK',
'       ,:P8_USO_PRETENTIDO',
'       ,:P8_USER_DEFINED',
'       ,:P8_PRODUCTCATEGORY',
'       ,:P8_NCM_COD_SERV',
'       ,:P8_PO_LINE_ID',
'       ,:P8_PO',
'       ,:P8_PO_HEADER_ID',
'       ,:P8_LINE_LOCATION_ID',
'       ,:P8_INFO',
'       ,:P8_ITEM_NUMBER',
'       ,:P8_DESCR',
'       ,:P8_INFO_ITEM',
'       ,:P8_UOM',
'       ,:P8_UOM_DESC_PO',
'       ,:P8_SOURCE_DOC_LINE_NUM',
'       ,:P8_TYPE_LIN',
'       ,:P8_NCM',
'       ,:P8_CFOP_IN',
'       ,:P8_SOURCE',
'       ,:P8_UNIT_PRICE_PO',
'       ,:P8_QUANT_LIN',
'       ,:P8_UNIT_PRICE_LIN',
'       ,:P8_TOTAL_LINHA',
' FROM rmais_efd_lines l,',
'      rmais_utilization_cfop util',
'where 1=1--efd_header_id = :P7_EFD_HEADER_ID',
'  and l.utilization_id  = util.id (+)',
'  AND l.efd_line_id = :P8_LINE_ID;',
'--',
':P8_TYPE2 := ''Goods'';',
'--',
'select Withholding ',
'  into :P8_WITHHOLD',
'  from rmais_efd_headers ',
' where efd_header_id = :P8_EFD_HEADER_ID;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1599713050452079716
);
