'DECLARE',
'  l NUMBER(15,2);',
'BEGIN',
'',
'  l := ( nvl(:P11_TOTAL_AMOUNT, 0) - (nvl(:P11_PIS_AMOUNT, 0) + nvl(:P11_COFINS_AMOUNT, 0) + nvl(:P11_INSS_TAX, 0) + nvl(:P11_INSS_AMOUNT, 0) + nvl(:P11_IR_AMOUNT, 0) + nvl(:P11_ISS_TAX, 0) + nvl(:P11_CSLL_AMOUNT, 0) + nvl(:P11_OTHER_EXPENSES_AMOUNT,'
||' 0) + nvl(:P11_DISCOUNT_AMOUNT, 0) ) );',
'',
'  if ( nvl(:P11_TOTAL_AMOUNT, 0) < 1 )',
'  THEN',
'    l := 0;',
'  END IF;',
'',
'  RETURN l;',
'',
'END;'))
,p_attribute_07=>'P11_TOTAL_AMOUNT,P11_PIS_AMOUNT,P11_COFINS_AMOUNT,P11_INSS_TAX,P11_INSS_AMOUNT,P11_IR_AMOUNT,P11_ISS_TAX,P11_CSLL_AMOUNT,P11_OTHER_EXPENSES_AMOUNT,P11_DISCOUNT_AMOUNT'
