wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1834148431128881030)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Collection_linhas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  execute immediate q''[alter session set NLS_NUMERIC_CHARACTERS=''.,'']'';',
'  begin',
'  --',
'  :P11_QTD := 1;',
'  --',
'  IF APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''RMAIS_LINHAS'') THEN',
'        APEX_COLLECTION.DELETE_COLLECTION(p_collection_name => ''RMAIS_LINHAS'');',
'        APEX_COLLECTION.CREATE_COLLECTION(p_collection_name => ''RMAIS_LINHAS'');',
'  ELSE',
'    APEX_COLLECTION.CREATE_COLLECTION(p_collection_name => ''RMAIS_LINHAS'');',
'  END IF;',
'  ',
'End;',
'    for x in (SELECT efd_header_id,',
'                     efd_line_id,',
'                     line_number,',
'                     fiscal_classification,',
'                     line_quantity,',
'                     unit_price,',
'                     line_amount,',
'                     item_description',
'FROM rmais_efd_lines',
' where efd_header_id = :P11_EFD_HEADER_ID',
' order by  line_number asc)',
'  loop',
'          APEX_COLLECTION.ADD_MEMBER(',
'              p_collection_name => ''RMAIS_LINHAS'',',
'              p_n001            => x.efd_header_id,',
'              p_n002            => x.efd_line_id,',
'              p_c001            => x.line_number,',
'              p_c002            => x.fiscal_classification,',
'              p_n003            => x.line_quantity,',
'              p_n004            => x.unit_price,',
'              p_n005            => x.line_amount,',
'              p_c003            => x.item_description',
'              );',
'',
'  end loop;',
'  --',
'  execute immediate q''[alter session set NLS_NUMERIC_CHARACTERS='',.'']'';',
'--',
'exception when others then',
'  raise_application_error(-20033,''Erro ao buscar PO'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1799862082297569122
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1834338216783189996)
,p_process_sequence=>100
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert_lines'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
' --:P11_EFD_HEADER_ID := nvl(:P11_EFD_HEADER_ID,xxrmais_invoices_s.nextval);',
'--',
'delete rmais_efd_lines where efd_header_id = :P11_EFD_HEADER_ID;',
'--',
'for regl in (select n001 efd_header_id,',
'                n002 efd_line_id,',
'                seq_id line_number,',
'                c002 fiscal_classification,',
'                n003 line_quantity,',
'                n004 unit_price,',
'                n005 line_amount,',
'                c003 item_description',
'            from apex_collections ',
'            where collection_name = ''RMAIS_LINHAS''',
'            order by seq_id asc)',
'    loop',
'        INSERT INTO rmais_efd_lines',
'        (efd_header_id , efd_line_id,creation_date,created_by,last_update_date,last_updated_by,line_number , fiscal_classification , line_quantity , unit_price ,line_amount , item_description )',
'        VALUES (:P11_EFD_HEADER_ID,rmais_efd_lines_s.nextval,SYSDATE,-1,SYSDATE,-1,regl.line_number,regl.fiscal_classification,regl.line_quantity , regl.unit_price , regl.line_amount , regl.item_description);',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1800051867951878088
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(194347824166278431)
,p_process_sequence=>110
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Limpar_boleto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P11_MODEL in (''06'',''21'',''22'',''28'',''29'') then',
'    :P11_BOLETO_COD := regexp_replace(:P11_BOLETO_COD,''[^[:digit:]]'');    ',
'else',
'    :P11_BOLETO_COD := null;',
'    :P11_FIRST_DUE_DATE := null;',
'end if;',
':P11_DOCUMENT_STATUS := ''N'';',
':P11_TIPO_ENTRADA := null;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
