wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1863292972970235520)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_DATA_INTO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'  --:P14_XMLF := '''';',
'  --:P14_XMLP := '''';',
'  --:P14_PDF  := '''';',
'  --:P14_XML  := '''';',
'',
'  BEGIN',
'    SELECT NVL(BLOB_FILENAME,pdf_filename),',
'         xml_filename',
'    INTO   :P14_PDF,',
'         :P14_XML',
'    FROM   RMAIS_EFD_HEADERS',
'    WHERE  efd_header_id = :P14_EFD_HEADER_ID',
'      AND  nvl(pdf_filename,BLOB_FILENAME) is not null;',
'  EXCEPTION WHEN OTHERS THEN ',
'    NULL;',
'  END;',
'',
'  BEGIN',
'',
'    SELECT numero',
'      INTO :P14_XMLF',
'      FROM rmais_ctrl_docs ct',
'         , rmais_efd_headers rh',
'     WHERE rh.doc_id = ct.id',
'       AND rh.model IN( ''55'', ''57'',''67'')',
'       AND rh.efd_header_id = :P14_EFD_HEADER_ID;',
'',
'  EXCEPTION WHEN OTHERS THEN ',
'    NULL;',
'  END;',
'',
'  :P14_XMLP := xxrmais_util_v2_pkg.get_link_nfse(:P14_EFD_HEADER_ID);',
'',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1829006624138923612
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1863291868242235509)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CLEAN_FIELDS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'  :P14_XMLF := null;',
'  :P14_XMLP := null;',
'  :P14_PDF  := null;',
'  :P14_XML  := null;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1829005519410923601
);
end;
