wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(622891547238588514)
,p_chart_id=>wwv_flow_imp.id(622891417988588513)
,p_seq=>10
,p_name=>'Series 1'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('select  case when C.LN = 1 then ''Canc. ap\00F3s Integra\00E7\00E3o'' else ''Cancelada'' end "Status",'),
'        sum(case ',
'            when C.LN = 1 and B.DOCUMENT_STATUS in(''T'',''UP'') then 1 ',
'            when C.LN = 2 and B.DOCUMENT_STATUS not in(''T'',''UP'') then 1 ',
'            else 0',
'        end) "Total"',
'from    RMAIS_BLACK_LIST_CANCEL A,',
'        RMAIS_EFD_HEADERS B,',
'        (select level LN from dual connect by level <= 2) C',
'where   A.ACCESS_KEY_NUMBER = B.ACCESS_KEY_NUMBER',
'and     poc is null',
'and     trunc(A.CREATION_DATE) >= nvl(to_date(:P31_DE,''DD/MM/YYYY''),trunc(A.CREATION_DATE))',
'group by C.LN',
'order by 2 desc'))
,p_max_row_count=>20
,p_ajax_items_to_submit=>'P31_DE,P31_ATE,P31_TOMADORES,P31_FORNECEDORES'
,p_series_name_column_name=>'Status'
