,p_chart_id=>wwv_flow_imp.id(570700329915285611)
,p_seq=>10
,p_name=>'Series 1'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  C.NCM "Ncm",',
'        C.TOTAL "Total"',
'from    (',
'            select  case when b.model = ''00'' then ',
'                      substr(lpad(replace(A.FISCAL_CLASSIFICATION,''.''),4,0),1,2)||''.''||substr(lpad(replace(A.FISCAL_CLASSIFICATION,''.''),4,0),3,2)',
'                    else',
'                      A.FISCAL_CLASSIFICATION',
'                    end NCM,',
'                    count(*) TOTAL',
'            from    RMAIS_EFD_LINES A,',
'                    RMAIS_EFD_HEADERS B',
'            where   A.EFD_HEADER_ID = B.EFD_HEADER_ID',
'            and     poc is null',
'            and     B.MODEL = :P31_FLAG_ITEM_FISCAL',
'            group by',
'                    A.FISCAL_CLASSIFICATION,',
'                    b.model',
'            order by 2 desc',
'        ) C',
'where rownum <= 10'))
,p_max_row_count=>20
,p_ajax_items_to_submit=>'P31_DE,P31_ATE,P31_TOMADORES,P31_FORNECEDORES,P31_FLAG_ITEM_FISCAL'
