 p_id=>wwv_flow_imp.id(844960039547352744)
,p_plug_name=>unistr('Defini\00E7\00E3o de determinante')
,p_parent_plug_id=>wwv_flow_imp.id(829231440615455563)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(1813179302715082248)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select   A.ID',
'        ,A.PRIORITY',
'        ,A.TYPE',
'        ,A.TYPE TYPE_DSP',
'        ,A.VALUE1',
'        ,A.ITEM',
'        ,A.CONTA',
'        ,A.CREATED_BY',
'        ,A.CREATION_DATE',
'        ,A.UPDATED_BY',
'        ,A.LAST_UPDATE_DATE',
'        ,A.MODEL',
'        ,A.SOURCE_DOC',
'        ,A.FLAG_RETENTION',
'        ,A.FLAG_NF_OP',
'        ,A.COMBINACAO_CONTABIL_GER',
'        ,A.PAYMENTMETHOD',
'from    RMAIS_DEFINE_DET_ENTRY A',
'where   A.MODEL = :P36_MODEL',
'--and     A.TYPE in (case when :P36_TYPE = ''NA'' then ''item_default'' else type end,case when :P36_TYPE = ''NA'' then ''find'' else type end)',
