wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1666334246882821880)
,p_plug_name=>unistr('Localiza\00E7\00E3o de erros de NFs')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(1813179302715082248)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with erros as (select ''Erro de envio ao Oracle'' d, ',
' 		''%(AP-%'' r',
'from dual',
'',
'union',
unistr('select ''Inv\00E1lidas - Pedidos n\00E3o localizados'' d, '),
unistr(' 		''%PO%N\00E3o localizada.%'' r'),
'from dual',
'union',
'select ''Erro de envio ao Oracle'' d, ',
' 		''The value of the attribute File Name isn%'' r',
'         from dual',
'union',
'select ''Erro de envio ao Oracle'' d, ',
' 		''Error: Entre em contato com o adminitrador do sistema'' r',
'         from dual',
'union',
'select ''Erro de envio ao Oracle'' d, ',
unistr(' 		''%Nota Fiscal%j\00E1 foi dispon\00EDbilizado para pagamento!% '' r'),
'from dual',
'union',
unistr('select ''Inv\00E1lidas - Mais de um pedido para escolha'' d, '),
' 		''%Mais de uma Ordem de Compra encontrada. Favor selecionar manualmente.%'' r',
'from dual',
'union',
unistr('select ''Inv\00E1lidas - Pedido ou recebimento com divergencia de quantidade ou valor'' d, '),
unistr(' 		''%Ordem de Compra%com diverg\00EAncia de quantidade%'' r'),
'from dual',
'union',
unistr('select ''Inv\00E1lidas - Pedido ou recebimento com divergencia de quantidade ou valor'' d, '),
unistr(' 		''%Ordem de Compra %encontrada com diverg\00EAncia de valor%'' r'),
'from dual',
'union',
unistr('select ''Inv\00E1lidas - Pedido ou recebimento com divergencia de quantidade ou valor'' d, '),
unistr(' 		''%N\00E3o foi poss\00EDvel fazer o split autom\00E1tico do recebimento f\00EDsico, recebimento com valor diverg\00EAnte da NF Quant de receb:%'' r'),
'from dual',
'',
'union',
unistr('select ''Inv\00E1lidas - Pedido ou recebimento com divergencia de quantidade ou valor'' d, '),
unistr(' 		''%Recebimento com valor diverg\00EAnte da NF Quant de receb:%'' r'),
'from dual',
'union',
unistr('select ''Email de fornecedor n\00E3o localizado'' d, '),
unistr(' 		''%N\00E3o foi localizado o email do fornecedor, verificar cadastro no ERP.%'' r'),
'from dual	 ',
'union',
unistr('select ''Diverg\00EAncia de imposto'' d, '),
unistr(' 		''%Identificado diverg\00EAncia entre c\00E1lculo de imposto, verifique o detalhe da linha.%'' r'),
'from dual		 ',
'union',
unistr('select ''Inv\00E1lidas - Pedido ultrapassou a toler\00E2ncia''d,'),
unistr('	''%Pedido ultrapassou a toler\00E2ncia permitida.%'' r'),
'from dual	',
'union',
'select ''Avisos''d,',
unistr('	''%Ordem de Compra%utilizando toler\00E2ncia%'' r'),
'from dual	',
'union',
'select ''Avisos''d,',
unistr('	''%Alterado quantidade e valor unit\00E1rio seguindo o pedido.%'' r'),
'from dual',
'union',
'select ''Avisos''d,',
unistr('	''%Encontrado recebimento f\00EDsico do documento fiscal.%'' r'),
'from dual',
'union',
'select ''Avisos''d,',
unistr('	''%Os pedidos escolhidos utilizaram %da toler\00E2ncia de%'' r'),
'from dual',
'union',
'select ''Avisos''d,',
unistr('	''%Ordem de Compra % sem utiliza\00E7\00E3o atrelada, utiliza\00E7\00E3o derivada pelo tipo fiscal.%'' r'),
'from dual',
'union',
'select ''Avisos''d,',
unistr('	''%Documento inv\00E1lido pela defini\00E7\00E3o do CFOP do documento fiscal'' r'),
'from dual',
'',
'union',
'select null d,  null r from dual		 )',
'--select * from erros;',
'',
'select distinct rm.*',
'        ',
',er.message_text --43133',
',count(*) over (partition by ''1'') total',
', nvl((select d from erros erb where er.message_text like erb.r),''N/D'') error',
unistr(',case when nvl(:P38_FILTRO_ERRO_PO,''N'') IN (''RI'',''INFORMADO'',''N'') then regexp_replace(replace(replace(er.message_text,''PO ''), ''N\00E3o localizada.''),''[^0-9]'') else null end pedido_nf'),
'from (SELECT   distinct',
'         h.efd_header_id',
'        ,h.source_document_type',
'        ,h.access_key_number',
'        ,h.document_number document_number',
'        ,h.series',
unistr('        ,decode(h.model,''55'',''NFe'',''00'',''NFse'',''NF'',''NF'',''57'',''Cte'',''67'',''CTEos'',''06'',''Energia'',''21'',''Comunica\00E7\00E3o'',''22'',''Telecomunica\00E7\00E3o'',''28'',''G\00E1s'',''29'',''\00C1gua'',''Modelo N\00E3o suportado'')  as model'),
'        ,h.model model_orig',
'        ,h.issue_date issue_date',
'        ,to_char(h.total_amount,''999G999G999G999G990D00'') total_amount',
unistr('        ,decode(h.document_status,''N'',''A Receber'',''V'',''V\00E1lido'',''I'',''Inv\00E1lido'',''E'',''Erro'',''T'',''Enviado ERP'',''C'',''Cancelada'',''M'',''Manual'',''X'',''Cancelada Ap\00F3s Integra\00E7\00E3o'',''R'',''Rejeitado'',''RW'',''Rejeitado'',''W'',''Z'',''Caixinha'',''Cancelada ERP'',''Status Descon')
||'hecido'')  document_status',
'        ,initcap(h.issuer_name) issuer_name',
'        ,h.issuer_document_number',
'        ,h.issuer_address',
'        ,initcap(org.nome) receiver_name',
'        ,org.cnpj receiver_document_number ',
'        ,nvl((select nvl(def.utilization_code,''COMPRA'') utilization_code',
'                from --rmais_efd_lines rml,',
'                    (select cfop_code , utilization_code ',
'                    from RMAIS_DEFINE_CFOP dcfo',
'                        ,RMAIS_DEFINE_UTILIZATION_CFOP dut',
'                    where dcfo.utilization_id = dut.utilization_id) def',
'',
'                    where 1=1----539003',
'                    and nvl(rml.cfop_from,''1111'') = def.cfop_code(+)',
'                    and rownum = 1',
'                    --and efd_header_id = h.efd_header_id',
'                    ),''COMPRA'') definicao_cfop',
'   FROM rmais_efd_headers h',
'        ,RMAIS_ORGANIZATIONS org',
'        ,rmais_efd_lines rml',
'    WHERE org.cnpj = h.receiver_document_number',
'    and rml.efd_header_id = h.efd_header_id) rm',
'    ,',
'    (',
'',
'SELECT --distinct l.line_number , nvl(ev.type,''Evento'') evento, message_text , trunc(ev.creation_date) "Data" ',
'     distinct case when ev.type||message_text like ''%Enviado para ERP%'' then null  else l.line_number end line_number',
'    , nvl(ev.type,''Evento'') ',
'    , message_text',
'    , trunc(ev.creation_date)',
'  , ev.efd_header_id ',
'FROM rmais_efd_lines l,',
'     RMAIS_EFD_LIN_VALID ev',
'WHERE (ev.efd_header_id = l.efd_header_id)',
'  AND (  L.efd_line_id  = ev.efd_line_id OR',
'         ev.efd_line_id IS NULL)   ',
unistr('  and (message_text not in(  ''Setup de De/Para de CFOP n\00E3o localizado.'') and'),
'  message_text not like ''%selecionada automaticamente pelo sistema%'' and',
'  message_text not like ''%Enviado para ERP%'' and',
'  message_text not like ''Split de linhas efetuado automaticamento pelo sistema.'' and',
unistr('  message_text not like ''Split de linhas efetuado automaticamento pelo sistema seguindo recebimento f\00EDsico.'' and'),
unistr('  message_text not like ''Alterado quantidade e valor unit\00E1rio seguindo o pedido.'' and'),
unistr('  message_text not like ''%Setup de De/Para de CFOP n\00E3o localizado. Utilization_code:%'''),
'  )',
') er',
'where er.efd_header_id  = rm.efd_header_id',
'and definicao_cfop = ''COMPRA''',
'and (((:P38_FILTRO_ERRO is not null)',
'and message_text like :P38_FILTRO_ERRO) or :P38_FILTRO_ERRO is null)',
'and (:P38_FILTRO_ERRO_PO is null or',
unistr('	((:P38_FILTRO_ERRO_PO = ''N_INFORMADO'' and message_text = ''PO  N\00E3o localizada.'') OR'),
unistr('	(:P38_FILTRO_ERRO_PO = ''INFORMADO'' and message_text <> ''PO  N\00E3o localizada.'')or'),
unistr('	(:P38_FILTRO_ERRO_PO = ''RI'' and message_text <> ''PO  N\00E3o localizada.'' and'),
unistr('	length (regexp_replace(replace(replace(message_text,''PO ''), ''N\00E3o localizada.''),''[^0-9]'')) = 6)'),
'	)) ',
'',
'',
'--AND trunc(issue_date) >= trunc(to_date(''06/08/2022'',''DD/MM/YYYY''))',
'AND trunc(issue_date) >= trunc(to_date(nvl(:P38_DATA_DE,''06/08/2022''),''DD/MM/YYYY''))',
unistr('and document_status IN (''Inv\00E1lido'',''Erro'',''V\00E1lido'')'),
'--order by access_key_number, issue_date '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P38_FILTRO_ERRO,P38_FILTRO_ERRO_PO,P38_DATA_DE'
,p_plug_display_condition_type=>'NEVER'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>unistr('Localiza\00E7\00E3o de erros de NFs')
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
