wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(13336433472651962594)
,p_plug_name=>unistr('Localiza\00E7\00E3o de erros de NFs')
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(1813179302715082248)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select rmv.*, ',
'    '''' pedido_nf',
'  from rmais_report_nf_erros_v rmv',
'  where trunc(issue_date) >= trunc(to_date(nvl(:P38_DATA_DE,''06/08/2022''),''DD/MM/YYYY''))',
'  ',
'  and MODALIDADE_ERRO = nvl(:P38_FILTRO_ERRO,MODALIDADE_ERRO)',
unistr('  and case when :P38_FILTRO_ERRO_PO is not null and (case when nvl(:P38_FILTRO_ERRO_PO,''N'') IN (''RI'',''INFORMADO'',''N'') then regexp_replace(replace(replace(rmv.message_text,''PO ''), ''N\00E3o localizada.''),''[^0-9]'') else null end) is not null then'),
'     ''1'' ',
'     when :P38_FILTRO_ERRO_PO is null then',
'     ''1''',
unistr('     when :P38_FILTRO_ERRO_PO = ''N_INFORMADO'' and (case when nvl(:P38_FILTRO_ERRO_PO,''N'') IN (''RI'',''INFORMADO'',''N'') then regexp_replace(replace(replace(rmv.message_text,''PO ''), ''N\00E3o localizada.''),''[^0-9]'') else null end) is  null then'),
'     ''1''',
'     else ''2'' end = ''1''',
'  and MODALIDADE_ERRO <> ''Avisos'''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P38_FILTRO_ERRO,P38_FILTRO_ERRO_PO,P38_DATA_DE'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>unistr('Localiza\00E7\00E3o de erros de NFs')
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
