wwv_flow_imp_page.create_page(
 p_id=>39
,p_name=>'Detalhes NF cobaia'
,p_alias=>'DETALHES-NF-COBAIA'
,p_step_title=>'Detalhes NF cobaia'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'function myFunction() {',
'  // Get the checkbox',
'  var checkBox = document.getElementById("myCheck");',
'',
'  // If the checkbox is checked, display the output text',
'  if (checkBox.checked == true){',
'    apex.item(''P7_CHECK_BOX_DEBUG'').setValue(''Y'');',
'  } else {',
'        apex.item(''P7_CHECK_BOX_DEBUG'').setValue(''N'');  ',
'  }',
'};'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.switch {',
'  position: relative;',
'  display: inline-block;',
'  width: 60px;',
'  height: 34px;',
'}',
'',
'/* Hide default HTML checkbox */',
'.switch input {',
'  opacity: 0;',
'  width: 0;',
'  height: 0;',
'}',
'',
'/* The slider */',
'.slider {',
'  position: absolute;',
'  cursor: pointer;',
'  top: 0;',
'  left: 0;',
'  right: 0;',
'  bottom: 0;',
'  background-color: rgb(204, 204, 204);',
'  -webkit-transition: .4s;',
'  transition: .4s;',
'}',
'',
'.slider:before {',
'  position: absolute;',
'  content: "";',
'  height: 26px;',
'  width: 26px;',
'  left: 4px;',
'  bottom: 4px;',
'  background-color: white;',
'  -webkit-transition: .4s;',
