,p_button_template_id=>wwv_flow_imp.id(1813243693728082280)
,p_button_image_alt=>unistr('Confir. da Opera\00E7\00E3o')
,p_button_position=>'CLOSE'
,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'l_aux varchar2(1);',
'begin',
'    begin',
'        SELECT ''Y'' ',
'        into l_aux',
'        FROM rmais_invoices_events ',
'        WHERE 1=1',
'        AND efd_header_id = :P39_EFD_HEADER_ID',
unistr('        AND evento = ''Manifesta\00E7\00E3o'''),
unistr('        AND mensagem = ''Conclus\00E3o de Opera\00E7\00E3o Realizada'';'),
'    exception when others then  ',
'      l_aux := ''N'';',
'    end;',
'if :P39_DOCUMENT_STATUS = ''T'' and l_aux = ''N'' and  :P39_MODEL = ''55'' then  ',
'  return true;',
'else',
'  return false;',
'end if;',
'end;'))
,p_button_condition2=>'PLSQL'
,p_button_condition_type=>'FUNCTION_BODY'
);
