wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(299047429125452762)
,p_validation_name=>'Boleto_duplicado'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    bol_exist number;',
'begin',
'    select count(*) into bol_exist ',
'        from rmais_efd_headers ',
'        where ',
'            :P39_BOLETO_COD is not null and :P39_EFD_HEADER_ID is not null',
'            and boleto_cod = nvl(:P39_BOLETO_COD,''0'') ',
'            and EFD_HEADER_ID != nvl(:P39_EFD_HEADER_ID,''0'');',
'    if bol_exist > 0 then',
'        return ''Boleto existente.'';',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(299010197354452737)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(299047814788452762)
,p_validation_name=>'Boleto_errado'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if (:P39_BOLETO_COD is null or length(regexp_replace(nvl(:P39_BOLETO_COD,0),''[^[:digit:]]'')) not in (48,47)) then',
unistr('    return ''Preencha o c\00F3digo de barras do boleto corretamente.''||length(regexp_replace(nvl(:P39_BOLETO_COD,0),''[^[:digit:]]''));'),
'end if;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(299010197354452737)
,p_associated_item=>wwv_flow_imp.id(299010644928452737)
,p_error_display_location=>'INLINE_WITH_FIELD'
