'       rmh.issuer_document_number,',
'       rmh.total_amount,',
unistr('       decode(rmh.document_status,''N'',''A Receber'',''V'',''V\00E1lido'',''I'',''Inv\00E1lido'',''E'',''Erro'',''T'',''Enviado ERP'',''C'',''Cancelada'',''M'',''Manual'',''X'',''Cancelada Ap\00F3s Integra\00E7\00E3o'',''R'',''Rejeitado'',''RW'',''Rejeitado'',''W'',''Cancelada ERP'',''Status Desconhecido'')  docum')
||'ent_status,',
'       rmh.operation_nature natureza_operacao,',
unistr('       decode(rmh.model,''55'',''NFe'',''00'',''NFse'',''NF'',''NF'',''57'',''Cte'',''67'',''CTEos'',''06'',''Energia'',''21'',''Comunica\00E7\00E3o'',''22'',''Telecomunica\00E7\00E3o'',''Modelo N\00E3o suportado'')  as model'),
'     ',
'  from RMAIS_TAXES_ERRORS_V rmv,',
'       rmais_efd_headers rmh',
'  where rmv.efd_header_id = rmh.efd_header_id',
'  and     nvl(rmv.valor,0) not between nvl(rmv.valor_imp,0) - 0.1 and nvl(rmv.valor_imp,0) + 0.1'))
